<script setup lang="ts">import type {Quality} from '../types/domain';import {propertyLabels} from '../constants/enums';import {fixed,pct} from '../utils/format';defineProps<{rows:Quality[]}>();const value=(key:string,v:number)=>key==='recycled'?pct(v):fixed(v,2)</script><template><div class="table-wrap"><table><thead><tr><th>质量属性</th><th>名义值</th><th>下界</th><th>上界</th><th>下界余量</th></tr></thead><tbody><tr v-for="r in rows" :key="r.property"><td>{{propertyLabels[r.property]}}</td><td>{{value(r.property,r.value)}}</td><td>{{value(r.property,r.minimum)}}</td><td>{{value(r.property,r.maximum)}}</td><td>{{value(r.property,r.lower_slack)}}</td></tr></tbody></table></div></template>
